// JAH demo program — Orchard pruning
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
var t={n:'claim',c:[{n:'evidence1',c:[]},{n:'refuted',c:[]},{n:'evidence2',c:[]}]};
t.c=t.c.filter(function(x){return x.n!=='refuted';});
check("refuted branch pruned", t.c.length, 2);
check("evidence remains", t.c[0].n, "evidence1");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

